from math import gcd
from collections import Counter, defaultdict

def transform(grid):
    h = len(grid); w = len(grid[0])
    cnt = Counter(v for row in grid for v in row)
    base = cnt.most_common(1)[0][0]
    markers = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
               if grid[r][c] != base and cnt[grid[r][c]] < 12]
    rows = sorted({r for r, c, _ in markers})
    cols = sorted({c for _, c, _ in markers})
    def spacing(vals):
        if len(vals) < 2:
            return 1
        d = 0
        for a, b in zip(vals, vals[1:]):
            d = gcd(d, b - a)
        return d or 1
    gr = spacing(rows); gc = spacing(cols)
    r0 = min(rows); c0 = min(cols)
    bycolor = defaultdict(list)
    for r, c, v in markers:
        bycolor[v].append((r, c))
    out = {}
    maxr = maxc = 0
    for v, cells in bycolor.items():
        n = len(cells); par = list(range(n))
        def find(x):
            while par[x] != x:
                par[x] = par[par[x]]; x = par[x]
            return x
        for i in range(n):
            for j in range(i + 1, n):
                if cells[i][0] == cells[j][0] or cells[i][1] == cells[j][1]:
                    par[find(i)] = find(j)
        groups = defaultdict(list)
        for i in range(n):
            groups[find(i)].append(cells[i])
        for g in groups.values():
            mr = min(a for a, b in g); mc = min(b for a, b in g)
            i = (mr - r0) // gr; j = (mc - c0) // gc
            out[(i, j)] = v
            maxr = max(maxr, i); maxc = max(maxc, j)
    return [[out.get((i, j), base) for j in range(maxc + 1)] for i in range(maxr + 1)]
